; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cyborgos (CyborgOS (a slot: CP/M 2.2 and the hypervisor's services)), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0100

NTC_TERM	equ 1		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 60		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 1		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld sp, ntc_cpmstack		; the platform's own real stack
			ld (ntc_csp), sp
			call ntc_cmdsave		; System.CommandLine: the command tail, before anything overwrites it
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them
			dw fn_system_commandline, var_system_commandline_commandline
			dw kw_strcpy, stmp0, var_system_commandline_commandline
			dw kw_strtrim, stmp0, stmp0
			dw kw_strcpy, var_a, stmp0
			dw kw_strval, var_a, tmp1
			dw p_cybsys_ask_c, lit_3, tmp1
			dw kw_vtov, var_cybsys_ask_ask, var_r
			dw kw_cpnevl, var_r, 0
			dw kw_goto_iffalse_n, if1_1
			dw kw_printstrvar, str0
			dw kw_printstrvar, var_a
			dw kw_printnl
if1_1:
			dw kw_stop

; ============================================================
; function ask (normal mode)
; ============================================================

p_cybsys_ask:
			dw kw_vtolptr8, var_cybsys_ask_op, arr_cybsys_b
			dw kw_vtolptr8, var_cybsys_ask_v, arr_cybsys_b+1
			dw p_cybsys_bdos_c, lit_131, vp_arr_cybsys_b
			dw kw_vtov, var_cybsys_bdos_bdos, var_cybsys_ask_ask
			dw p_cybsys_ask_r

; ============================================================
; function bdos (normal mode)
; ============================================================

p_cybsys_bdos:
			dw asm_1_337_n
			dw p_cybsys_bdos_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================


p_cybsys_ask_c:		; call ask (normal)
			pop hl			; op
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_cybsys_ask_op), de
			pop hl			; v
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_cybsys_ask_v), de
			ld hl, 0
			ld (var_cybsys_ask_ask), hl
			ld (p_cybsys_ask_rs), sp
			ld sp, p_cybsys_ask
			jp ntc_xn
p_cybsys_ask_r:		; end of ask
			ld sp, (p_cybsys_ask_rs)
			jp ntc_xn
p_cybsys_bdos_c:		; call bdos (normal)
			pop hl			; f
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_cybsys_bdos_f), de
			pop hl			; d
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_cybsys_bdos_d), de
			ld hl, 0
			ld (var_cybsys_bdos_bdos), hl
			ld (p_cybsys_bdos_rs), sp
			ld sp, p_cybsys_bdos
			jp ntc_xn
p_cybsys_bdos_r:		; end of bdos
			ld sp, (p_cybsys_bdos_rs)
			jp ntc_xn

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

asm_1_337_n:		; #asm, CybSys.cls line 337 (normal)
            ld (var_cybsys_hsp), sp
            ld sp, (ntc_csp)
            ld a, (var_cybsys_bdos_f)
            ld c, a
            ld de, (var_cybsys_bdos_d)
            ei                      ; (CP/M's BDOS: interrupts on)
            call 5
            di                      ; (off before SP is the threaded code again: it comes back with them on)
            ld l, a
            ld h, 0
            ld (var_cybsys_bdos_bdos), hl
            ld sp, (var_cybsys_hsp)
			ret			; end of #asm

fn_system_commandline:		; function commandline (asm keyword), System.cls line 68
            pop hl
            jp ntc_cmdget
			ret			; end of #asm


; ============================================================
